import json, math, sys
from collections import defaultdict
sys.path.insert(0,'/workspace/task_file/scripts')
from cost_model import CostModel, align, HEADS, HIDDEN, CostConsts
cm=CostModel(64)
C=cm.c

def load(b):
    return [json.loads(l) for l in open(f'/workspace/task_file/input_data/requests_bucket_{b}.jsonl')]

def fc(S,g):
    ss=cm._sum_sq_arith(S,g); sl=g*S+g*(g-1)/2
    return C.Kd_attn*ss + C.Kd_mlp*HIDDEN*sl
def fl(S,g):
    ss=cm._sum_sq_arith(S,g); sl=g*S+g*(g-1)/2
    return C.Td_attn*ss + C.Td_mlp*HIDDEN*sl
def prefcost(p):
    S=align(p,64); return C.Kp_attn*S*S + C.Kp_mlp*S*HIDDEN
def preflat(p):
    S=align(p,64); return C.Tp_attn*S*S + C.Tp_mlp*S*HIDDEN

def build_groups(reqs):
    g=defaultdict(list)
    for r in reqs: g[r['gen_len']].append(r)
    groups={}
    for gv,rs in g.items():
        byS=defaultdict(list)
        for r in rs: byS[align(r['prompt_len'],64)].append(r)
        groups[gv]=[ (S,byS[S]) for S in sorted(byS) ]
    return groups

def gen_options(gv, sg, lam):
    # sg list (S, list reqs) sorted
    m=len(sg)
    # prefix counts
    pref=[0]
    for S,rs in sg: pref.append(pref[-1]+len(rs))
    INF=float('inf')
    dp=[INF]*(m+1); par=[-1]*(m+1); dc=[0.0]*(m+1); ds=[0.0]*(m+1)
    dp[0]=0
    for j in range(1,m+1):
        Sj=sg[j-1][0]
        for i in range(1,j+1):
            n=pref[j]-pref[i-1]
            cc=n*fc(Sj,gv)+C.Kbatch_overhead_cost
            cs=preflat(Sj)+fl(Sj,gv)+C.Tbatch_overhead_ms
            val=dp[i-1]+cc+lam*cs
            if val<dp[j]:
                dp[j]=val; par[j]=i-1; dc[j]=dc[i-1]+cc; ds[j]=ds[i-1]+cs
    # reconstruct clusters as (i,j)
    clusters=[]; j=m
    while j>0:
        i=par[j]; clusters.append((i+1,j)); j=i
    clusters.reverse()
    return dc[m],ds[m],clusters

def make_batches(groups, lam):
    batches=[]
    for gv in sorted(groups):
        sg=groups[gv]
        c,s,clusters=gen_options(gv,sg,lam)
        for i,j in clusters:
            reqs=[]
            for t in range(i-1,j): reqs+=sg[t][1]
            batches.append(reqs)
    return batches

def eval_batches(reqs,batches,reps=None):
    reqmap={r['request_id']:r for r in reqs}
    smaxs=[max(align(r['prompt_len'],64) for r in b) for b in batches]
    if reps is None:
        reps=choose_reps(smaxs,8)
    plan=[]
    for bi,b in enumerate(batches):
        s=next(rep for rep in reps if rep>=smaxs[bi])
        for r in b:
            plan.append({'request_id':r['request_id'],'batch_id':f'b-{bi:05d}',
                         'shape':{'seq_align':s,'heads_align':32,'hidden_align':4096}})
    m=cm.plan_metrics(reqmap,plan)
    return {k:m[k] for k in ['cost','pad_ratio','p95_latency_ms','sequential_timecost']},reps

def choose_reps(vals,K):
    u=sorted(set(vals))
    if len(u)<=K: return u
    cnt=defaultdict(int)
    for v in vals: cnt[v]+=1
    import functools
    n=len(u); INF=float('inf')
    def groupcost(i,j):
        s=sum(cnt[u[t]] for t in range(i,j+1)); r=u[j]
        return (C.Kshape_attn*r*r+C.Kshape_mlp*r*HIDDEN)*s
    dp=[[INF]*n for _ in range(K+1)]; par=[[-1]*n for _ in range(K+1)]
    for j in range(n): dp[1][j]=groupcost(0,j)
    for k in range(2,K+1):
        for j in range(n):
            for i in range(1,j+1):
                if dp[k-1][i-1]<INF:
                    c=dp[k-1][i-1]+groupcost(i,j)
                    if c<dp[k][j]: dp[k][j]=c;par[k][j]=i-1
    bk=min(range(1,K+1),key=lambda k:dp[k][n-1])
    reps=[];j=n-1;k=bk
    while k>=1:
        reps.append(u[j]);j=par[k][j];k-=1
    return sorted(reps)

